import type { EngineInterface, Register } from 'claude-code'

type Thumb = { base64: string; columns: number; rows: number }

const TOKEN = /\[Image #(\d+)\]/g
const HAS_TOKEN = /\[Image #\d+\]/
const SOURCE = /\[Image: source: ([^\]\n]+)\]/g
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

// The card is at most this many cells. A cell is about twice as tall as it is wide.
const MAX_COLUMNS = 40
const MAX_ROWS = 14
const BACKGROUND = '#373737'

// Image number to the file the engine pasted it from.
const paths = new Map<string, string>()
const thumbs = new Map<string, Thumb | null>()
const running = new Map<string, Promise<Thumb | null>>()
const gaveUp = new Set<string>()
let pending: string[] = []
let hydrating: Promise<void> | null = null

// The row that names a file is stored after the prompt row, so a first draw can come too early.
const ATTEMPTS = 8
const RETRY_MS = 150

function hash(text: string): string {
  let h = 0x811c9dc5

  for (let n = 0; n < text.length; n++) {
    h = Math.imul(h ^ text.charCodeAt(n), 0x01000193)
  }

  return (h >>> 0).toString(16) + text.length.toString(16)
}

// A prompt row names the numbers; the row after it names the files, in the same order.
function note(text: string, into: Map<string, string>, waiting: string[]): string[] {
  const numbers = [...new Set([...text.matchAll(TOKEN)].map(match => match[1]))]
  const sources = [...text.matchAll(SOURCE)].map(match => match[1])
  const names = numbers.length > 0 ? numbers : waiting

  if (sources.length === 0) {
    return names
  }

  sources.forEach((file, n) => {
    if (names[n] !== undefined && !into.has(names[n])) {
      into.set(names[n], file)
    }
  })

  return []
}

async function hydrate($: EngineInterface) {
  const found = new Map<string, string>()
  let waiting: string[] = []

  for (const message of await $.session.messages()) {
    if (message.role === 'user') {
      waiting = note(message.text, found, waiting)
    }
  }

  for (const [number, file] of found) {
    if (!paths.has(number)) {
      paths.set(number, file)
    }
  }
}

// Width and height sit at bytes 16 to 23 of a PNG: the first 32 base64 characters hold them.
function pngSize(base64: string): { width: number; height: number } | null {
  const bytes: number[] = []
  const head = base64.slice(0, 32)

  for (let n = 0; n < head.length; n += 4) {
    const a = ALPHABET.indexOf(head[n])
    const b = ALPHABET.indexOf(head[n + 1])
    const c = ALPHABET.indexOf(head[n + 2])
    const d = ALPHABET.indexOf(head[n + 3])
    bytes.push((a << 2) | (b >> 4), ((b & 15) << 4) | (c >> 2), ((c & 3) << 6) | d)
  }

  const read = (at: number) => ((bytes[at] << 24) | (bytes[at + 1] << 16) | (bytes[at + 2] << 8) | bytes[at + 3]) >>> 0
  const width = read(16)
  const height = read(20)

  return width > 0 && height > 0 ? { width, height } : null
}

async function makeThumb($: EngineInterface, file: string): Promise<Thumb | null> {
  const output = `/tmp/image-preview-${hash(file)}.png`
  const run = await $.process.run(['sips', '-s', 'format', 'png', '-Z', '640', file, '--out', output], {
    timeoutMs: 15_000,
  })

  if (run.exitCode !== 0) {
    return null
  }

  const { base64 } = await $.fs.read(output, { as: 'bytes' })
  const size = pngSize(base64)

  if (!size) {
    return null
  }

  const aspect = size.height / size.width
  let columns = MAX_COLUMNS
  let rows = Math.round((columns * aspect) / 2)

  if (rows > MAX_ROWS) {
    rows = MAX_ROWS
    columns = Math.round((rows * 2) / aspect)
  }

  return { base64, columns: Math.max(1, columns), rows: Math.max(1, rows) }
}

async function thumbFor($: EngineInterface, number: string): Promise<Thumb | null> {
  const file = paths.get(number)

  if (!file) {
    return null
  }

  if (thumbs.has(file)) {
    return thumbs.get(file) ?? null
  }

  let job = running.get(file)

  if (!job) {
    job = makeThumb($, file).catch(() => null)
    running.set(file, job)
  }

  const thumb = await job
  thumbs.set(file, thumb)
  running.delete(file)

  return thumb
}

export const register: Register = on => {
  // Drawing is pure, so the files are noted when a row is stored.
  on('session.append', async ($, e, next) => {
    const result = await next(e)

    if (e.message.type === 'user') {
      for (const block of e.message.content) {
        if (block.type === 'text' && typeof block.text === 'string') {
          pending = note(block.text, paths, pending)
        }
      }
    }

    return result
  })

  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    if (e.surface !== 'terminal' || e.props.origin.kind !== 'composer' || !HAS_TOKEN.test(e.props.text)) {
      return next(e)
    }

    const numbers = [...new Set([...e.props.text.matchAll(TOKEN)].map(match => match[1]))]

    for (let attempt = 0; attempt < ATTEMPTS; attempt++) {
      const missing = numbers.filter(number => !paths.has(number) && !gaveUp.has(number))

      if (missing.length === 0) {
        break
      }

      hydrating ??= hydrate($)
        .catch(() => undefined)
        .finally(() => {
          hydrating = null
        })
      await hydrating

      if (missing.every(number => paths.has(number))) {
        break
      }

      if (attempt === ATTEMPTS - 1) {
        missing.forEach(number => gaveUp.add(number))
      } else {
        await $.clock.sleep(RETRY_MS)
      }
    }

    const drawn = new Map<string, Thumb | null>()
    await Promise.all(numbers.map(async number => drawn.set(number, await thumbFor($, number))))

    if ([...drawn.values()].every(thumb => thumb === null)) {
      return next(e)
    }

    const { Box, Image, Text } = $.ui.resolve(e)

    return (
      <Box backgroundColor={BACKGROUND} flexDirection="row">
        <Text dimColor>{'❯ '}</Text>
        <Box flexDirection="column" flexGrow={1}>
          {e.props.text.split('\n').map((line, i) => (
            <Box key={`l${i}`} flexDirection="row" flexWrap="wrap">
              {line.split(/(\[Image #\d+\])/).map((part, j) => {
                if (part === '') {
                  return null
                }

                const number = /^\[Image #(\d+)\]$/.exec(part)?.[1]
                const thumb = number === undefined ? null : drawn.get(number)

                if (!thumb) {
                  return <Text key={`t${i}-${j}`}>{part}</Text>
                }

                return (
                  <Box key={`k${i}-${j}`}>
                    <Text color="blue" hover={{ underline: true }}>
                      {part}
                    </Text>
                    <Box
                      position="absolute"
                      top={-(thumb.rows + 2)}
                      left={0}
                      display="none"
                      hover={{ display: 'flex' }}
                      borderStyle="round"
                      borderColor="gray"
                    >
                      <Image
                        key={`p${i}-${j}`}
                        source={{ png: thumb.base64 }}
                        columns={thumb.columns}
                        rows={thumb.rows}
                        alt={part}
                      />
                    </Box>
                  </Box>
                )
              })}
            </Box>
          ))}
        </Box>
      </Box>
    )
  })
}

